	// Could not queue (e.g. agent still starting): wait for the session
	// to unlock and then process the message instead of dropping it.
	go func() {
		ticker := time.NewTicker(100 * time.Millisecond)
		defer ticker.Stop()
		timeout := time.NewTimer(10 * time.Minute)
		defer timeout.Stop()
		for !session.TryLock() {
			select {
			case <-e.ctx.Done():
				return
			case <-timeout.C:
				e.reply(p, msg.ReplyCtx, e.i18n.T(MsgPreviousProcessing))
				return
			case <-ticker.C:
			}
		}
